package com.mfrp.plens.service.evaluation;import com.mfrp.plens.config.CohortCriteria;import com.mfrp.plens.model.ProjectSubmission;import org.springframework.stereotype.Service;
@Service public class RuleBasedEvaluationService{public void evaluate(ProjectSubmission s){String text=(s.getTitle()+" "+s.getProblemStatement()+" "+s.getObjectives()+" "+s.getTechnologyStack()).toLowerCase();int matches=(int)CohortCriteria.REQUIRED_KEYWORDS.stream().filter(k->text.contains(k.toLowerCase())).count();s.setAlignmentScore(Math.min(100,20+matches*16+(s.getDocumentationLink()==null||s.getDocumentationLink().isBlank()?0:10)));s.setOverlapScore(0);}}
